schoolEffect:
function schoolEffect(school, target, x, y, damage, excluded = []) {
  if (school === "water") {
    const level = effectLevel("water-attack");
    if (level) skillVisual("splash", x, y, { radius: UPGRADE_TUNING.splashBaseRadius + level * UPGRADE_TUNING.splashPerLevel });
    if (level) for (const other of combatTargets()) if (other !== target && Math.hypot(deltaX(other.x, x), deltaY(other.y, y)) < UPGRADE_TUNING.splashBaseRadius + level * UPGRADE_TUNING.splashPerLevel) hitBuildTarget(other, damage * (BUILD_TUNING.splashDamageBase + level * BUILD_TUNING.splashDamageGrowth));
    if ((effectLevel("water-skill") || effectLevel("fusion-puddle"))) addField("water", x, y);
  }
  if (school === "wind") return; // 入門只提升水球速度；擊退由旋風處理。
  if (school === "thunder") {
    const visited = [target, ...excluded];
    const chain=cardBlock('thunder-attack','onChain').actions[0];
    const modifier=effectLevel('thunder-super') ? cardBlock('thunder-super','onChain').actions[0] : null;
    const jumps=chain.count+(modifier?modifier.extra:0), radius=chain.radius;
    for (let i=0;i<jumps;i++) {
      const other = combatTargets().filter(e => !visited.includes(e) && Math.hypot(deltaX(e.x,x),deltaY(e.y,y)) <= radius).sort((a,b) => Math.hypot(deltaX(a.x,x),deltaY(a.y,y))-Math.hypot(deltaX(b.x,x),deltaY(b.y,y)))[0];
      if (!other) break;
      visited.push(other); lightning(x,y,other.x,other.y);
      hitBuildTarget(other, damage * (modifier?modifier.multiplier:chain.multiplier));
      x=other.x;y=other.y;
      if(state.mode!=='playing') return;
    }
  }
}

addField:
function addField(school, x, y, radius) {
  const block=school === "thunder" ? cardBlock("fusion-dash","onDashTrail").actions[0] : null;
  if(radius===undefined) radius=block?block.radius:BUILD_TUNING.fieldRadius;
  if (state.fields.length >= (block?block.limit:BUILD_TUNING.fieldLimit)) state.fieldPool.push(state.fields.shift());
  state.fields.push(takeFromPool(state.fieldPool, { school, x, y, radius: radius * (1 + Math.max(0, effectLevel(school === "water" ? "water-skill" : "wind-dash") - 1) * (block?block.radiusGrowth:BUILD_TUNING.fieldRadiusGrowth)), life: block?block.seconds:BUILD_TUNING.fieldSeconds, timer: 0 }));
}

updateFields:
function updateFields(dt) {
  for (let i = state.fields.length - 1; i >= 0; i--) {
    const field = state.fields[i]; field.life -= dt; field.timer -= dt;
    if (field.life <= 0) { state.fieldPool.push(state.fields.splice(i, 1)[0]); continue; }
    if (field.timer > 0) continue;
    const block=field.school === "thunder" ? cardBlock("fusion-dash","onDashTrail").actions[0] : null;
    field.timer += block?block.interval:BUILD_TUNING.fieldInterval;
    for (const target of combatTargets()) {
      if (Math.hypot(deltaX(target.x, field.x), deltaY(target.y, field.y)) > field.radius + target.r) continue;
      const level = field.school === "water" ? Math.max(effectLevel("water-skill"), effectLevel("water-dash"), effectLevel("fusion-storm")) : field.school === "wind" ? effectLevel("wind-dash") : effectLevel("fusion-dash");
      hitBuildTarget(target, block?block.damage:BUILD_TUNING.fieldDamage * Math.max(1, level));
      if (field.school === "water") {
        target.wetTimer = GAME_DATA.schoolRules.wetSeconds;
        target.slowTimer = BUILD_TUNING.slowSeconds; target.makerSlow = 0;
        if (effectLevel("fusion-puddle")) { lightning(field.x, field.y, target.x, target.y); hitBuildTarget(target, BUILD_TUNING.fieldDamage * effectLevel("fusion-puddle")); burst(target.x, target.y, BUILD_TUNING.thunder.color, 3); }
      }
      if (field.school === "wind") shiftTarget(target, field.x, field.y, BUILD_TUNING.pushDistance * Math.max(1, level));
      if (field.school === "thunder") schoolEffect("thunder", target, target.x, target.y, block.damage);
      if (state.mode !== "playing") return;
    }
  }
}

leaveDashTrail:
function leaveDashTrail(x, y, distance, fromX = x, fromY = y) {
  // 沿走過的路每隔一小段留痕跡，速度變快時也不會留下大空洞。
  const spacing = Math.max(1, effectLevel("fusion-dash") ? cardBlock("fusion-dash","onDashTrail").actions[0].spacing : BUILD_TUNING.trailSpacing);
  let next = Math.max(0, spacing - state.trailDistance);
  while (next <= distance) {
    const fraction = distance > 0 ? next / distance : 0;
    for (const school of ["water", "wind", "thunder"]) if ((school === "water" && (effectLevel("water-dash") || effectLevel("fusion-storm"))) || (school === "wind" && (effectLevel("wind-dash") || effectLevel("fusion-storm"))) || (school === "thunder" && effectLevel("fusion-dash"))) addField(school, fromX + (deltaX(x, fromX)) * fraction, fromY + (deltaY(y, fromY)) * fraction);
    for (const card of UPGRADES) if (upgradeLevel(card.id)) for (const effect of card.effects) {
      if (!effect.feature && effect.type === "dash-trail" && effect.trigger === "dash") executeMakerEffect(effect, fromX + (deltaX(x, fromX))*fraction, fromY + (deltaY(y, fromY))*fraction, upgradeLevel(card.id));
    }
    next += spacing;
  }
  state.trailDistance = (state.trailDistance + distance) % spacing;
}

updateOneUltimate:
function updateOneUltimate(dt, selectedSchool) {
  if (state.ultimateVisual) { state.ultimateVisual.life -= dt; if (state.ultimateVisual.life <= 0) state.ultimateVisual = null; }
  const ultimateSchool = selectedSchool;
  const card = ultimateSchool ? { school: ultimateSchool, id: ultimateSchool + "-ultimate" } : null;
  if (!card) return;
  state.ultimateTimer = countdown(state.ultimateTimer || 0, dt);
  if (state.ultimateTimer > 0) {
    if (card.school === "wind" && state.ultimateVisual) {
      state.ultimateVisual.x = state.player.x + Math.cos(state.elapsed * BUILD_TUNING.tornadoSpeed) * BUILD_TUNING.tornadoRadius;
      state.ultimateVisual.y = state.player.y + Math.sin(state.elapsed * BUILD_TUNING.tornadoSpeed) * BUILD_TUNING.tornadoRadius;
    }
    return;
  }
  const thunderBlock=card.school === "thunder" ? cardBlock(card.id,"onUltimate") : null;
  const level = effectLevel(card.id), damage = thunderBlock ? thunderBlock.actions[0].amount : BUILD_TUNING.ultimateDamage * (1 + (level - 1) * BUILD_TUNING.ultimateGrowth);
  let targets = combatTargets();
  const x = state.player.x + Math.cos(state.elapsed * BUILD_TUNING.tornadoSpeed) * BUILD_TUNING.tornadoRadius;
  const y = state.player.y + Math.sin(state.elapsed * BUILD_TUNING.tornadoSpeed) * BUILD_TUNING.tornadoRadius;
  if (card.school === "thunder") targets = SurvivorEffectBlocks.select(thunderBlock,targets,targets.length?Math.random():0);
  if (card.school === "wind") targets = targets.filter(target => Math.hypot(deltaX(target.x, x), deltaY(target.y, y)) < BUILD_TUNING.fieldRadius + target.r);
  state.ultimateVisual = { worldWidth: state.worldWidth, worldHeight: state.worldHeight, school: card.school, x: card.school === "thunder" && targets.length ? targets[0].x : x, y: card.school === "thunder" && targets.length ? targets[0].y : y, life: card.school === "water" ? 1.2 : .5 };
  state.ultimateTimer = card.school === "water" ? BUILD_TUNING.ultimateSeconds : card.school === "wind" ? BUILD_TUNING.tornadoTick : thunderBlock.interval;
  for (const target of targets) { if (card.school === "thunder") lightning(target.x, target.y - 90, target.x, target.y); hitBuildTarget(target, damage); burst(target.x, target.y, BUILD_TUNING[card.school].color, 5); if (state.mode !== "playing") return; }
}

updateBomb:
function updateBomb(dt) {
  if (state.bombBlast) { state.bombBlast.life -= dt; if (state.bombBlast.life <= 0) state.bombBlast = null; }
  const bomb = state.bomb;
  if (!bomb) return;
  bomb.timer -= dt;
  if (bomb.timer > 0.000001) return;
  state.bomb = null; state.bombBlast = { x: bomb.x, y: bomb.y, radius: bomb.radius, life: 0.35, schools: bomb.schools };
  if (bomb.schools.includes("wind")) for (const target of combatTargets()) {
    if (Math.hypot(deltaX(target.x, bomb.x), deltaY(target.y, bomb.y)) <= bomb.radius * BUILD_TUNING.skillRadiusMultiplier + target.r) shiftTarget(target, bomb.x, bomb.y, -BUILD_TUNING.pullDistance);
  }
  if (bomb.schools.includes("water")) addField("water", bomb.x, bomb.y, bomb.radius);
  if (bomb.schools.includes("thunder")) {
    const block=cardBlock("thunder-skill","onSkillBlast",{radius:bomb.radius,damage:bomb.damage});
    skillVisual("discharge", bomb.x, bomb.y, { radius: bomb.radius, color: "#7737b0" });
    for (const target of combatTargets()) {
      if (cardBlockMatches(block.conditions[0],target,bomb.x,bomb.y)) { lightning(bomb.x, bomb.y, target.x, target.y); applyCardTargetActions(block,target); }
      if (state.mode !== "playing") return;
    }
  }
  function pushAway(target) {
    shiftTarget(target,bomb.x,bomb.y,bomb.knockback,true);
  }
  for (const enemy of state.enemies) {
    if (!enemy.alive || !canAttackTarget(enemy) || Math.hypot(deltaX(enemy.x, bomb.x), deltaY(enemy.y, bomb.y)) > bomb.radius + enemy.r) continue;
    damageEnemy(enemy, bomb.damage);
    if (enemy.alive) { pushAway(enemy); enemy.knockback = 0; }
  }
  if (state.boss && canAttackTarget(state.boss) && Math.hypot(deltaX(state.boss.x, bomb.x), deltaY(state.boss.y, bomb.y)) <= bomb.radius + state.boss.r) {
    state.boss.hp -= schoolDamage(state.boss, bomb.damage); state.boss.flash = HIT_FLASH_SECONDS; state.boss.meleeFlash=false; pushAway(state.boss); updateHud();
    if (state.boss.hp <= 0) { state.boss = null; finishRun(true); }
  }
  burst(bomb.x, bomb.y, "#80eaff", 20); playSound("explosion");
}

absorbSchoolHit:
function absorbSchoolHit(damage) {
  if (damage > 0 && state.schoolCombat && state.schoolCombat.bubble) {
    state.schoolCombat.bubble = false;
    skillVisual('splash',state.player.x,state.player.y,{radius:50,color:BUILD_TUNING.water.color});
    return 0;
  }
  return SurvivorWeapons.receivedDamage(damage, activeWeapon());
}

schoolDashEnded:
function schoolDashEnded() {
  const c = state.schoolCombat, r = GAME_DATA.schoolRules;
  if (!c) return;
  if (effectLevel('water-bubble')) c.bubble = true;
  if (effectLevel('wind-refund')) {
    // 半格是回充進度，不能用半格再發動一次完整衝刺。
    state.dashCooldown = Math.max(0, state.dashCooldown - gameSettings.dashCooldown * r.refundCharge);
    if (state.dashCooldown === 0 && state.dashCharges < maxDashCharges()) { state.dashCharges++; state.dashCooldown = state.dashCharges < maxDashCharges() ? gameSettings.dashCooldown : 0; }
  }
}

schoolShotHit:
function schoolShotHit(shot, target) {
  const r = GAME_DATA.schoolRules;
  if ((shot.schools || []).includes('water') || effectLevel('water-skill')) target.wetTimer = r.wetSeconds;
  if (!shot.melee) waveNeutralHit(target,shot.vx,shot.vy);
  if (shot.push) shiftTarget(target, shot.x - shot.vx, shot.y - shot.vy, shot.push);
  if (shot.charged) { lightning(state.player.x,state.player.y,target.x,target.y); schoolEffect('thunder',target,target.x,target.y,shot.damage,shot.hitList); }
  if (!shot.melee && effectLevel('wind-blade') && shot.pierce > 0 && !shot.blade) {
    const other = combatTargets().find(e => !shot.hitList.includes(e) && Math.hypot(deltaX(e.x,target.x),deltaY(e.y,target.y)) <= r.windBladeRange);
    skillVisual('gust',target.x,target.y,{x2:target.x+shot.vx*.15,y2:target.y+shot.vy*.15,color:BUILD_TUNING.wind.color});
    if (other && state.projectiles.length < PROJECTILE_LIMIT) {
      const a = Math.atan2(deltaY(other.y,target.y),deltaX(other.x,target.x));
      state.projectiles.push(takeFromPool(state.projectilePool,{x:target.x,y:target.y,vx:Math.cos(a)*PROJECTILE_SPEED,vy:Math.sin(a)*PROJECTILE_SPEED,r:5,damage:shot.damage*r.windBladeDamage,rangeLeft:r.windBladeRange,hitList:[target],alive:true,blade:true,pierce:0,schools:[],colors:['wind'],transformed:false,push:0,charged:false,maker:true}));
    }
  }
}

updateSchoolCombat:
function updateSchoolCombat(dt) {
  const c = state.schoolCombat, r = GAME_DATA.schoolRules;
  if (!c) return;
  c.still = state.moveRate > .01 ? 0 : c.still + dt;
  for (const target of state.enemies.concat(state.boss ? [state.boss] : [])) target.wetTimer = countdown(target.wetTimer || 0,dt);
  const pulse = (id, seconds, action) => {
    if (!effectLevel(id)) return;
    c.timers[id] = (c.timers[id] === undefined ? seconds : c.timers[id]) - dt;
    if (c.timers[id] > 0) return;
    c.timers[id] += seconds; action();
  };
  const push = (radius, distance, color) => {
    skillVisual('discharge',state.player.x,state.player.y,{radius,color,life:.4});
    for (const target of combatTargets()) if (Math.hypot(deltaX(target.x,state.player.x),deltaY(target.y,state.player.y)) <= radius) shiftTarget(target,state.player.x,state.player.y,distance);
  };
  pulse('water-fountain',r.fountainSeconds,() => { push(r.fountainRadius,r.fountainPush,BUILD_TUNING.water.color); for (const t of combatTargets()) if (Math.hypot(deltaX(t.x,state.player.x),deltaY(t.y,state.player.y)) <= r.fountainRadius) t.wetTimer=r.wetSeconds; });
  pulse('wind-gust',r.gustSeconds,() => push(r.gustRadius,r.gustPush,BUILD_TUNING.wind.color));
  pulse('water-rain',r.rainSeconds,() => {
    c.rain = r.rainDuration;
    // 下雨是全場緩速，不造成畫面外傷害。
    for (const target of state.enemies.concat(state.boss ? [state.boss] : [])) { target.slowTimer=r.rainDuration; target.makerSlow=0; target.wetTimer=r.wetSeconds; }
    skillVisual('splash',state.player.x,state.player.y,{radius:r.fountainRadius,color:BUILD_TUNING.water.color,life:.8});
  });
  c.rain = countdown(c.rain || 0,dt);
  if (c.rain > 0) for (const t of state.enemies.concat(state.boss ? [state.boss] : [])) { t.slowTimer=Math.max(t.slowTimer || 0,dt*2); t.makerSlow=0; t.wetTimer=r.wetSeconds; }
  const summon=cardBlock('thunder-rod','onSummonTimer'), rodBlock=summon.actions[0];
  pulse('thunder-rod',summon.interval,() => { if (c.rods.length < rodBlock.limit) c.rods.push({x:state.player.x,y:state.player.y,life:rodBlock.seconds,timer:0}); });
  for (const rod of c.rods) {
    rod.life -= dt; rod.timer -= dt;
    if (rod.timer <= 0) {
      rod.timer += rodBlock.interval;
      skillVisual('sparkle',rod.x,rod.y,{radius:20,color:BUILD_TUNING.thunder.color,life:.5});
      for (const target of combatTargets()) if (Math.hypot(deltaX(target.x,rod.x),deltaY(target.y,rod.y)) <= rodBlock.radius) { lightning(rod.x,rod.y,target.x,target.y); hitBuildTarget(target,rodBlock.damage); if(state.mode!=='playing') return; }
    }
  }
  c.rods = c.rods.filter(rod => rod.life > 0);
  if (schoolWindWall()) for (const target of combatTargets()) if (Math.hypot(deltaX(target.x,state.player.x),deltaY(target.y,state.player.y)) < r.eyeRadius + target.r) shiftTarget(target,state.player.x,state.player.y,r.eyePush*dt);
  applyEffectBlockTimer(dt);

}

shot:
function shot(number, kills, chargedUsed, powers, rules) {
    const big = powers.drop && number % rules.bigDropEvery === 0;
    const charge = SurvivorEffectBlocks.charge(kills,chargedUsed,powers.charge,{schoolRules:rules});
    const charged = charge.charged;
    return { size: big ? rules.bigDropSize : 1, damage: (big ? rules.bigDropDamage : 1) * charge.multiplier, push: big ? rules.bigDropPush : 0, charged: !!charged };
  }
